#!/usr/bin/env bash
# Seeds a test VM with sites, snippets and global options for manual testing
# (docs/wiki/Manual-Testing.md). Run from the repo root: npm run vm:seed [vm]
#
# The config is generated by the plugin's own writers (sites.seed.ts), copied to the VM and
# installed by setup.sh, which backs up /etc/caddy first. The e2e fixtures reset the config,
# so run this again after an e2e run.
set -euo pipefail
cd "$(dirname "$0")/../.."

vm="${1:-arch}"
case "$vm" in
  arch) port=2230 ;; debian) port=2231 ;; fedora) port=2232 ;;
  *) echo "unknown VM: $vm (arch, debian, fedora)" >&2; exit 1 ;;
esac

out=.vms/seed-out
rm -rf "$out" && mkdir -p "$out"
SEED_OUT="$PWD/$out" npx vitest run --config scripts/seed-vm/vitest.config.ts >/dev/null
cp scripts/seed-vm/setup.sh "$out/"

tar cz -C "$out" . | ssh -p "$port" -i .vms/id_ed25519 -o IdentitiesOnly=yes -o IdentityAgent=none \
  -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o LogLevel=error test@localhost \
  'rm -rf /tmp/seed && mkdir /tmp/seed && tar xz -C /tmp/seed && sudo bash /tmp/seed/setup.sh'
